function buildRaw(to, subject, html) {
  const mime = [
    'From: Hector Meza <h.mezarealty@gmail.com>',
    `To: ${to}`,
    'Reply-To: hmeza@briggsfreeman.com',
    `Subject: ${subject}`,
    'MIME-Version: 1.0',
    'Content-Type: text/html; charset=UTF-8',
    '',
    html
  ].join('\r\n');
  return Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
const raw = $input.first().json;
const link = 'https://g.page/r/CabJGOEHci6qEBM/review';
let clients = [], hood = '', closing = 'bought';

if (raw.body && Array.isArray(raw.body.clients)) {
  clients = raw.body.clients; hood = (raw.body.neighborhood || '').trim();
  closing = (raw.body.closing || 'bought').toLowerCase();
} else if (raw['Client 1 first name']) {
  clients.push({ first: raw['Client 1 first name'], email: raw['Client 1 email'] });
  if (raw['Client 2 first name'] && raw['Client 2 email']) {
    clients.push({ first: raw['Client 2 first name'], email: raw['Client 2 email'] });
  }
  hood = (raw['Neighborhood'] || '').trim();
  closing = (raw['Bought or sold'] || 'bought').toLowerCase();
}
clients = clients.filter(c => c && c.first && c.email);
if (!clients.length) { throw new Error('No clients in payload'); }

const sig = `<p style="margin:24px 0 0;">With gratitude,<br><strong>Hector Meza</strong><br>Briggs Freeman Sotheby's International Realty<br>(214) 686-5641 &middot; <a href="https://hectormeza.com" style="color:#1a3c34;">hectormeza.com</a></p>`;
return clients.map((c, i) => {
  const partner = clients.length > 1 ? clients.find((x, j) => j !== i) : null;
  const opener = closing === 'sold'
    ? `Now that everything is signed and your sale${hood ? ' in ' + hood : ''} is officially complete, I wanted to take a moment to say thank you.`
    : `Now that everything is signed and the ${hood ? 'home in ' + hood : 'home'} is officially yours, I wanted to take a moment to say thank you.`;
  const partnerPara = partner
    ? `<p style="margin:0 0 16px;">One small note: Google reviews are tied to each person's account, so if ${partner.first} would like to share their side as well, each voice counts on its own. No pressure whatsoever.</p>`
    : '';
  const html = [
    `<div style="font-family:'Aptos','Segoe UI',Calibri,Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#222;max-width:560px;">`,
    `<p style="margin:0 0 16px;">Hi ${c.first},</p>`,
    `<p style="margin:0 0 16px;">${opener} Being trusted with something this big is never lost on me, and working with you made it a genuine pleasure.</p>`,
    `<p style="margin:0 0 16px;">If I may ask one small favor: would you share a few words about your experience on Google? It takes about two minutes, and it means more than you might think. A few honest sentences from you carry more weight than anything I could say about myself.</p>`,
    `<p style="margin:0 0 20px;"><a href="${link}" style="display:inline-block;background:#1a3c34;color:#ffffff;padding:12px 24px;border-radius:6px;text-decoration:none;font-weight:bold;">Leave a review</a></p>`,
    `<p style="margin:0 0 16px;font-size:13px;color:#777;">Or copy this link: ${link}</p>`,
    partnerPara,
    `<p style="margin:0 0 16px;">I'm here for the long haul. Contractor recommendations, market questions, or just to catch up, my door is always open. Congratulations again.</p>`,
    sig,
    `</div>`
  ].join('');
  return { json: {
    first: c.first, email: c.email, partner: partner ? partner.first : '',
    neighborhood: hood, closing, sent_at: new Date().toISOString(),
    subject: `Congratulations again, ${c.first}`, html, raw: buildRaw(c.email, `Congratulations again, ${c.first}`, html)
  }};
});

